1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root { --cell: 28px; }
9	  * { box-sizing: border-box; }
10	  body {
11	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
12	    background: #14161c; color: #e8e8ee; font: 15px/1.4 system-ui, sans-serif;
13	  }
14	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
15	  .board {
16	    display: grid; grid-template-columns: repeat(10, var(--cell)); grid-template-rows: repeat(20, var(--cell));
17	    gap: 1px; background: #2a2d36; border: 2px solid #3a3e4a;
18	  }
19	  .cell { width: var(--cell); height: var(--cell); background: #1c1f27; }
20	  .side { display: flex; flex-direction: column; gap: 14px; min-width: 130px; }
21	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: #8a8fa0; }
22	  .stat .value { font-size: 22px; font-weight: 600; }
23	  .preview { display: grid; grid-template-columns: repeat(4, 18px); grid-template-rows: repeat(2, 18px); gap: 1px; margin-bottom: 8px; }
24	  .preview .mini { width: 18px; height: 18px; background: transparent; }
25	  .help { font-size: 12px; color: #8a8fa0; }
26	  .game-over { font-size: 18px; font-weight: 700; color: #ff6b6b; }
27	  .p-I { background: #00c8e0 !important; }
28	  .p-O { background: #f0d000 !important; }
29	  .p-T { background: #a040f0 !important; }
30	  .p-S { background: #30c050 !important; }
31	  .p-Z { background: #e03030 !important; }
32	  .p-J { background: #3060f0 !important; }
33	  .p-L { background: #f08c20 !important; }
34	</style>
35	</head>
36	<body>
37	<div class="game">
38	  <div class="board" data-testid="board" id="board"></div>
39	  <div class="side">
40	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
41	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
42	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
43	    <div class="stat"><div class="label">Next</div><div id="next" data-testid="next-piece"></div></div>
44	    <div class="game-over" data-testid="game-over" id="game-over" hidden>Game over</div>
45	    <div class="help">← → move<br>↑ or X rotate<br>↓ soft drop<br>Space hard drop</div>
46	  </div>
47	</div>
48	<script>
49	(function () {
50	  var ROWS = 20, COLS = 10, LETTERS = ["I", "O", "T", "S", "Z", "J", "L"];
51	
52	  // [REQ-001] spawn shapes as [row, col] on the board
53	  var SHAPES = {
54	    I: [[0, 3], [0, 4], [0, 5], [0, 6]],
55	    O: [[0, 4], [0, 5], [1, 4], [1, 5]],
56	    T: [[0, 4], [1, 3], [1, 4], [1, 5]],
57	    S: [[0, 4], [0, 5], [1, 3], [1, 4]],
58	    Z: [[0, 3], [0, 4], [1, 4], [1, 5]],
59	    J: [[0, 3], [1, 3], [1, 4], [1, 5]],
60	    L: [[0, 5], [1, 3], [1, 4], [1, 5]]
61	  };
62	
63	  // [REQ-002] rotation box per piece: size and spawn origin (top-left of the box on the board)
64	  var BOX = {
65	    I: { size: 4, origin: [-1, 3] },
66	    O: { size: 2, origin: [0, 4] },
67	    T: { size: 3, origin: [0, 3] }, S: { size: 3, origin: [0, 3] }, Z: { size: 3, origin: [0, 3] },
68	    J: { size: 3, origin: [0, 3] }, L: { size: 3, origin: [0, 3] }
69	  };
70	  var KICKS = [0, -1, 1, -2, 2];  // sideways shifts tried when a rotation does not fit
71	  var LOCK_TICKS = 2;             // [REQ-002] ticks unable to fall before a piece locks
72	  var MAX_LOCK_RESETS = 3;        // [REQ-002] lock delay restarts allowed per piece
73	  // [REQ-003] points per clear by rows at once, times level; clearing together always beats one at a time
74	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
75	  var SOFT_DROP_POINTS = 1, HARD_DROP_POINTS = 2;  // [REQ-003] per cell moved down by the player
76	  var QUEUE_SIZE = 3;             // [REQ-004] upcoming pieces kept in the queue
77	  var PREVIEW_COUNT = 1;          // [REQ-006] upcoming pieces shown in the preview
78	
79	  var state = {
80	    board: [],      // board[row][col] = letter or null
81	    current: null,  // { type, cells: [[r,c],...], origin: [r,c], lockTicks, lockResets }
82	    upcoming: [],
83	    score: 0, level: 1, lines: 0,
84	    status: "running"
85	  };
86	  var timer = null;
87	
88	  var boardEl = document.getElementById("board");
89	  var cellEls = [];
90	  for (var r = 0; r < ROWS; r++) {
91	    cellEls.push([]);
92	    for (var c = 0; c < COLS; c++) {
93	      var el = document.createElement("div");
94	      el.className = "cell";
95	      el.setAttribute("data-testid", "cell");
96	      el.setAttribute("data-row", r);
97	      el.setAttribute("data-col", c);
98	      boardEl.appendChild(el);
99	      cellEls[r].push(el);
100	    }
101	  }
102	
103	  function emptyBoard() {
104	    var b = [];
105	    for (var r = 0; r < ROWS; r++) { b.push(new Array(COLS).fill(null)); }
106	    return b;
107	  }
108	
109	  function randomLetter() {
110	    return LETTERS[Math.floor(Math.random() * LETTERS.length)];
111	  }
112	
113	  function validLetters(queue) {
114	    return (Array.isArray(queue) ? queue : []).filter(function (l) { return SHAPES[l]; });
115	  }
116	
117	  // [REQ-004] keep enough upcoming pieces to fill the preview, padding with random ones
118	  function fillUpcoming() {
119	    while (state.upcoming.length < QUEUE_SIZE) state.upcoming.push(randomLetter());
120	  }
121	
122	  // [REQ-001] take the next piece from the queue, falling back to random
123	  function takeNext() {
124	    var letter = state.upcoming.length ? state.upcoming.shift() : randomLetter();
125	    fillUpcoming();
126	    return letter;
127	  }
128	
129	  // [REQ-004] a new piece that does not fit where it spawns ends the game
130	  function spawn() {
131	    var type = takeNext();
132	    var cells = SHAPES[type].map(function (p) { return [p[0], p[1]]; });
133	    if (!fits(cells)) {
134	      state.current = null;
135	      state.status = "gameover";
136	      if (timer) { clearInterval(timer); timer = null; }
137	      return;
138	    }
139	    state.current = {
140	      type: type,
141	      cells: cells,
142	      origin: BOX[type].origin.slice(),
143	      lockTicks: 0, lockResets: 0
144	    };
145	  }
146	
147	  function fits(cells) {
148	    return cells.every(function (p) {
149	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && !state.board[p[0]][p[1]];
150	    });
151	  }
152	
153	  function canMove(dr, dc) {
154	    return fits(state.current.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; }));
155	  }
156	
157	  function tryMove(dr, dc) {
158	    if (!state.current || !canMove(dr, dc)) return false;
159	    var cur = state.current;
160	    cur.cells = cur.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; });
161	    cur.origin = [cur.origin[0] + dr, cur.origin[1] + dc];
162	    if (dr > 0) cur.lockTicks = 0;
163	    return true;
164	  }
165	
166	  // [REQ-002] rotate clockwise inside the piece's box; try sideways shifts; refuse if nothing fits
167	  function tryRotateCW() {
168	    var cur = state.current, n = BOX[cur.type].size, o = cur.origin;
169	    var turned = cur.cells.map(function (p) {
170	      var lr = p[0] - o[0], lc = p[1] - o[1];
171	      return [o[0] + lc, o[1] + n - 1 - lr];
172	    });
173	    // a rotation near the top edge is pushed down just enough to stay on the board
174	    var dr = Math.max(0, -Math.min.apply(null, turned.map(function (p) { return p[0]; })));
175	    for (var i = 0; i < KICKS.length; i++) {
176	      var dc = KICKS[i];
177	      var cand = turned.map(function (p) { return [p[0] + dr, p[1] + dc]; });
178	      if (fits(cand)) {
179	        cur.cells = cand;
180	        cur.origin = [o[0] + dr, o[1] + dc];
181	        return true;
182	      }
183	    }
184	    return false;
185	  }
186	
187	  // [REQ-002] [REQ-005] restart the lock delay, at most MAX_LOCK_RESETS times per piece
188	  function restartLockDelay() {
189	    var cur = state.current;
190	    if (cur.lockResets < MAX_LOCK_RESETS) { cur.lockResets++; cur.lockTicks = 0; }
191	  }
192	
193	  // [REQ-002] sideways move; while resting it restarts the lock delay
194	  function shift(dc) {
195	    var resting = !canMove(1, 0);
196	    if (tryMove(0, dc) && resting) restartLockDelay();
197	  }
198	
199	  // [REQ-003] [REQ-005] soft drop scores per cell; on a resting piece it restarts the lock delay like a sideways move
200	  function softDrop() {
201	    if (tryMove(1, 0)) state.score += SOFT_DROP_POINTS;
202	    else restartLockDelay();
203	  }
204	
205	  // [REQ-003] remove full rows, drop everything above, count lines and score the clear
206	  function clearLines() {
207	    var kept = state.board.filter(function (row) { return !row.every(Boolean); });
208	    var cleared = ROWS - kept.length;
209	    if (!cleared) return;
210	    while (kept.length < ROWS) kept.unshift(new Array(COLS).fill(null));
211	    state.board = kept;
212	    state.lines += cleared;
213	    state.score += CLEAR_POINTS[cleared] * state.level;
214	  }
215	
216	  // [REQ-001] [REQ-003] lock the falling piece, clear full rows and spawn the next one
217	  function lock() {
218	    var cur = state.current;
219	    cur.cells.forEach(function (p) {
220	      if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) state.board[p[0]][p[1]] = cur.type;
221	    });
222	    clearLines();
223	    spawn();
224	  }
225	
226	  // [REQ-001] [REQ-002] one gravity step: fall one row, or count one tick of lock delay
227	  function gravityStep() {
228	    if (state.status !== "running") return;
229	    if (!state.current) spawn();
230	    else if (!tryMove(1, 0) && ++state.current.lockTicks >= LOCK_TICKS) lock();
231	    render();
232	  }
233	
234	  // [REQ-001] [REQ-002] [REQ-003] player actions; hard drop locks at once, with no delay; drops score per cell
235	  function input(action) {
236	    if (state.status !== "running" || !state.current) return;
237	    if (action === "left") shift(-1);
238	    else if (action === "right") shift(1);
239	    else if (action === "rotateCW") tryRotateCW();
240	    else if (action === "softDrop") softDrop();
241	    else if (action === "hardDrop") {
242	      while (tryMove(1, 0)) state.score += HARD_DROP_POINTS;
243	      lock();
244	    }
245	    render();
246	  }
247	
248	  // [REQ-001] synchronous render from the real game state
249	  function render() {
250	    var drawn = state.board.map(function (row) { return row.slice(); });
251	    if (state.current) {
252	      state.current.cells.forEach(function (p) {
253	        if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) drawn[p[0]][p[1]] = state.current.type;
254	      });
255	    }
256	    for (var r = 0; r < ROWS; r++) {
257	      for (var c = 0; c < COLS; c++) {
258	        var el = cellEls[r][c], letter = drawn[r][c];
259	        el.className = letter ? "cell p-" + letter : "cell";
260	        el.setAttribute("data-filled", letter ? "true" : "false");
261	        el.setAttribute("data-piece", letter || "");
262	      }
263	    }
264	    document.getElementById("score").textContent = String(state.score);
265	    document.getElementById("level").textContent = String(state.level);
266	    document.getElementById("lines").textContent = String(state.lines);
267	    renderNext();
268	    document.getElementById("game-over").hidden = state.status !== "gameover";
269	  }
270	
271	  // [REQ-004] [REQ-006] only the next piece, coloured as on the board
272	  function renderNext() {
273	    var box = document.getElementById("next");
274	    box.innerHTML = "";
275	    state.upcoming.slice(0, PREVIEW_COUNT).forEach(function (type) {
276	      var grid = document.createElement("div");
277	      grid.className = "preview";
278	      grid.setAttribute("data-testid", "next-piece-item");
279	      grid.setAttribute("data-piece", type);
280	      var filled = {};
281	      SHAPES[type].forEach(function (p) { filled[p[0] + "," + (p[1] - 3)] = true; });
282	      for (var r = 0; r < 2; r++) {
283	        for (var c = 0; c < 4; c++) {
284	          var m = document.createElement("div");
285	          m.className = filled[r + "," + c] ? "mini p-" + type : "mini";
286	          grid.appendChild(m);
287	        }
288	      }
289	      box.appendChild(grid);
290	    });
291	  }
292	
293	  function startTimer() {
294	    if (timer) clearInterval(timer);
295	    timer = setInterval(gravityStep, 1000);
296	  }
297	
298	  // [REQ-001] start a fresh game, optionally with a fixed piece queue
299	  function newGame(queue) {
300	    state.board = emptyBoard();
301	    state.score = 0; state.level = 1; state.lines = 0;
302	    state.status = "running";
303	    state.upcoming = validLetters(queue);
304	    state.current = null;
305	    spawn();
306	    startTimer();
307	    render();
308	  }
309	
310	  // [REQ-001] test control surface
311	  window.__tetris = {
312	    newGame: newGame,
313	    setQueue: function (queue) {
314	      state.upcoming = validLetters(queue);
315	      fillUpcoming();
316	      render();
317	    },
318	    setBoard: function (rows) {
319	      var b = emptyBoard();
320	      for (var r = 0; r < ROWS; r++) {
321	        var line = (rows && rows[r]) || "";
322	        for (var c = 0; c < COLS; c++) {
323	          var ch = line.charAt(c);
324	          b[r][c] = SHAPES[ch] ? ch : null;
325	        }
326	      }
327	      state.board = b;
328	      render();
329	    },
330	    tick: function (n) {
331	      if (n === undefined) n = 1;
332	      for (var i = 0; i < n; i++) gravityStep();
333	    },
334	    input: input,
335	    getBoard: function () {
336	      return state.board.map(function (row) {
337	        return row.map(function (v) { return v || "."; }).join("");
338	      });
339	    },
340	    getState: function () {
341	      return {
342	        current: state.current
343	          ? {
344	              type: state.current.type,
345	              cells: state.current.cells.map(function (p) { return [p[0], p[1]]; }),
346	              lockTicks: state.current.lockTicks,
347	              lockResets: state.current.lockResets
348	            }
349	          : null,
350	        next: state.upcoming.slice(),
351	        score: state.score, level: state.level, lines: state.lines,
352	        status: state.status
353	      };
354	    }
355	  };
356	
357	  document.addEventListener("keydown", function (e) {
358	    var map = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", x: "rotateCW", X: "rotateCW", " ": "hardDrop", Spacebar: "hardDrop" };
359	    var action = map[e.key];
360	    if (!action) return;
361	    e.preventDefault();
362	    input(action);
363	  });
364	
365	  newGame();
366	})();
367	</script>
368	</body>
369	</html>
