p='index.html'; s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
rep('''    <div class="stat"><div class="label">Next</div><div id="next" data-testid="next-piece"></div></div>''',
'''    <div class="stat"><div class="label">Next</div><div id="next" data-testid="next-piece"></div></div>
    <div class="stat"><div class="label">Hold</div><div id="hold" data-testid="hold-piece" data-piece=""></div></div>''')
rep('''Space hard drop</div>''','''Space hard drop<br>C or Shift hold</div>''')
rep('''  var PREVIEW_COUNT = 1;          // [REQ-006] upcoming pieces shown in the preview
''','''  var PREVIEW_COUNT = 1;          // [REQ-006] upcoming pieces shown in the preview
  var LINES_PER_LEVEL = 10;       // [REQ-007] lines cleared for each level gained
''')
rep('''    upcoming: [],
    score: 0, level: 1, lines: 0,''','''    upcoming: [],
    hold: null, holdUsed: false,  // [REQ-007] held letter; true once this piece has used its hold
    score: 0, level: 1, lines: 0,''')
rep('''  // [REQ-004] a new piece that does not fit where it spawns ends the game
  function spawn() {
    var type = takeNext();''','''  // [REQ-004] [REQ-007] a new piece that does not fit where it spawns ends the game; type defaults to the next in queue
  function spawn(type) {
    type = type || takeNext();''')
rep('''    state.lines += cleared;
    state.score += CLEAR_POINTS[cleared] * state.level;
  }''','''    state.score += CLEAR_POINTS[cleared] * state.level;
    // [REQ-007] one level per 10 lines crossed, counted on from the current level
    var gained = Math.floor((state.lines + cleared) / LINES_PER_LEVEL) - Math.floor(state.lines / LINES_PER_LEVEL);
    state.lines += cleared;
    if (gained > 0) { state.level += gained; startTimer(); }
  }

  // [REQ-007] milliseconds between gravity steps at the current level
  function dropInterval() {
    return Math.max(100, 1000 - (state.level - 1) * 100);
  }

  // [REQ-007] put the falling piece aside, or swap it with the held one; once per piece
  function holdPiece() {
    if (state.holdUsed) return;
    var held = state.hold;
    state.hold = state.current.type;
    state.holdUsed = true;
    spawn(held);
  }''')
rep('''    clearLines();
    spawn();''','''    clearLines();
    state.holdUsed = false;
    spawn();''')
rep('''    else if (action === "softDrop") softDrop();''','''    else if (action === "softDrop") softDrop();
    else if (action === "hold") holdPiece();''')
rep('''    renderNext();
''','''    renderNext();
    renderHold();
''')
rep('''    state.upcoming.slice(0, PREVIEW_COUNT).forEach(function (type) {
      var grid = document.createElement("div");
      grid.className = "preview";
      grid.setAttribute("data-testid", "next-piece-item");
      grid.setAttribute("data-piece", type);
      var filled = {};
      SHAPES[type].forEach(function (p) { filled[p[0] + "," + (p[1] - 3)] = true; });
      for (var r = 0; r < 2; r++) {
        for (var c = 0; c < 4; c++) {
          var m = document.createElement("div");
          m.className = filled[r + "," + c] ? "mini p-" + type : "mini";
          grid.appendChild(m);
        }
      }
      box.appendChild(grid);
    });
  }

  function startTimer() {
    if (timer) clearInterval(timer);
    timer = setInterval(gravityStep, 1000);
  }''','''    state.upcoming.slice(0, PREVIEW_COUNT).forEach(function (type) {
      var grid = miniGrid(type);
      grid.setAttribute("data-testid", "next-piece-item");
      box.appendChild(grid);
    });
  }

  // [REQ-007] the held piece, coloured as on the board
  function renderHold() {
    var box = document.getElementById("hold");
    box.innerHTML = "";
    box.setAttribute("data-piece", state.hold || "");
    if (state.hold) box.appendChild(miniGrid(state.hold));
  }

  function miniGrid(type) {
    var grid = document.createElement("div");
    grid.className = "preview";
    grid.setAttribute("data-piece", type);
    var filled = {};
    SHAPES[type].forEach(function (p) { filled[p[0] + "," + (p[1] - 3)] = true; });
    for (var r = 0; r < 2; r++) {
      for (var c = 0; c < 4; c++) {
        var m = document.createElement("div");
        m.className = filled[r + "," + c] ? "mini p-" + type : "mini";
        grid.appendChild(m);
      }
    }
    return grid;
  }

  // [REQ-007] gravity timer at the level's speed; stays stopped once the game is over
  function startTimer() {
    if (timer) clearInterval(timer);
    timer = state.status === "running" ? setInterval(gravityStep, dropInterval()) : null;
  }''')
rep('''    state.score = 0; state.level = 1; state.lines = 0;
    state.status = "running";''','''    state.score = 0; state.level = 1; state.lines = 0;
    state.hold = null; state.holdUsed = false;
    state.status = "running";''')
rep('''    tick: function (n) {''','''    // [REQ-007] set the level for testing; gravity speed follows
    setLevel: function (n) {
      state.level = Math.max(1, Math.floor(n) || 1);
      startTimer();
      render();
    },
    tick: function (n) {''')
rep('''        next: state.upcoming.slice(),''','''        next: state.upcoming.slice(),
        hold: state.hold,
        dropInterval: dropInterval(),''')
rep('''" ": "hardDrop", Spacebar: "hardDrop" };''','''" ": "hardDrop", Spacebar: "hardDrop", c: "hold", C: "hold", Shift: "hold" };''')
open(p,'w').write(s)
EOF
sed -n '/<script>/,/<\/script>/p' index.html | sed '1d;$d' > "$TMPDIR/t.js" 2>/dev/null; node --check "$TMPDIR/t.js" && echo ok
